import './style.css';

/*
 * @author: @joao-carmassi
 * @description: Animated rainbow gradient border effect — same animation as Button's rainbow effect.
 * Drop <RainbowBorder /> inside any Card (with `relative` on the Card).
 * The Card itself needs the rainbow background classes applied; use the `className` on Card.
 * @version: 1.1.0
 * @date: 2026-24-03
 * @license: MIT
 */

/**
 * Helper: CSS classes to apply directly on the Card to give it the rainbow border look.
 * Pass these into the Card's `className`.
 *
 * @example
 * <Card className={cn("relative", rainbowCardClasses)}>
 *   <RainbowBorder />
 *   ...
 * </Card>
 */
export const rainbowCardClasses =
  'animate-rainbow-effect border-0 bg-[linear-gradient(var(--card),var(--card)),linear-gradient(var(--card)_50%,color-mix(in_oklch,var(--card)_60%,transparent)_80%,transparent),linear-gradient(90deg,oklch(66.2%_0.225_25.9)_0%,oklch(90.7%_0.231_133)_20%,oklch(69.6%_0.165_251)_40%,oklch(80.2%_0.134_225)_60%,oklch(60.4%_0.26_302)_80%,oklch(66.2%_0.225_25.9)_100%)] bg-size-[200%] [background-clip:padding-box,border-box,border-box] bg-origin-border [border:calc(0.125rem)_solid_transparent]';

/**
 * Decorative glow element rendered below the card. Place <RainbowBorder /> inside the Card.
 * The glow relies on `overflow-visible` (or removing `overflow-hidden`) from the Card
 * because it renders outside the card bottom edge.
 */
function RainbowBorder(): React.ReactNode {
  return (
    <div
      className='pointer-events-none absolute bottom-[-20%] left-1/2 z-0 h-1/5 w-3/5 -translate-x-1/2 animate-rainbow-effect bg-[linear-gradient(90deg,oklch(66.2%_0.225_25.9),oklch(90.7%_0.231_133),oklch(69.6%_0.165_251),oklch(80.2%_0.134_225),oklch(60.4%_0.26_302))] filter-[blur(0.75rem)]'
      aria-hidden='true'
    />
  );
}

export { RainbowBorder };

[data-variant='default'] {
  --pulse-color: var(--primary);
}
[data-variant='destructive'] {
  --pulse-color: var(--destructive);
}
[data-variant='secondary'] {
  --pulse-color: var(--secondary-foreground);
}
[data-variant='outline'] {
  --pulse-color: var(--ring);
}
[data-variant='ghost'] {
  --pulse-color: var(--ring);
}

.before\:animate-shine-effect::before {
  animation: shine-effect 3s ease-out infinite;
}

.animate-rainbow-effect {
  animation: rainbow-effect 3s linear infinite;
}

.animate-pulsating-effect {
  animation: pulsating-effect 1.5s ease-out infinite;
}

.card-shine-effect {
  animation: card-shine-effect var(--duration) infinite linear;
}

@keyframes shine-effect {
  0% {
    background-position: 200% 0;
  }
  25% {
    background-position: -200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

@keyframes rainbow-effect {
  0% {
    background-position: 0%;
  }
  100% {
    background-position: 200%;
  }
}

@keyframes pulsating-effect {
  0% {
    box-shadow: 0 0 0 0 var(--pulse-color, currentColor);
  }
  70% {
    box-shadow: 0 0 0 8px transparent;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}

@keyframes card-shine-effect {
  0% {
    background-position: 0% 0%;
  }
  50% {
    background-position: 100% 100%;
  }
  to {
    background-position: 0% 0%;
  }
}

/* ─── Aura Beam ─────────────────────────────────────────────────────────── */

@property --aura-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

@keyframes aura-spin {
  to {
    --aura-angle: 360deg;
  }
}

.aura-beam {
  --aura-padding: 2px;
  --aura-radius: 0.75rem;
  --aura-duration: 6s;
  --aura-color: var(--primary);
  --aura-color-from: var(--aura-color);
  --aura-color-to: var(--aura-color);

  position: relative;
  display: inline-block;
  padding: var(--aura-padding);
  border-radius: calc(var(--aura-radius) + var(--aura-padding));
  color: var(--aura-color);

  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    transparent 220deg,
    currentColor 280deg,
    currentColor 360deg
  );

  animation: aura-spin var(--aura-duration) linear infinite;
}

.aura-beam > * {
  position: relative;
  z-index: 2;
  border-radius: var(--aura-radius);
}

.aura-beam::before,
.aura-beam::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: inherit;
  pointer-events: none;
  z-index: 0;
}

.aura-beam::before {
  filter: blur(6px);
  opacity: 0.65;
}

.aura-beam::after {
  filter: blur(18px);
  opacity: 0.35;
}

/* ─── Beam variant ────────────────────────────────────────────────────────── */

.aura-beam[data-variant='beam'] {
  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    transparent 275deg,
    var(--aura-color-from) 305deg,
    var(--aura-color-to) 325deg,
    transparent 360deg
  );
}

.aura-beam[data-variant='beam']::before {
  filter: blur(4px);
  opacity: 0.85;
}

.aura-beam[data-variant='beam']::after {
  filter: blur(22px);
  opacity: 0.55;
}

/* ─── Shine variant ───────────────────────────────────────────────────────── */

@keyframes aura-shine {
  0% {
    background-position: 00% 00%;
  }
  50% {
    background-position: 100% 100%;
  }
  100% {
    background-position: 00% 00%;
  }
}

.aura-beam[data-variant='shine'] {
  background-image: radial-gradient(
    transparent,
    transparent,
    var(--aura-color),
    transparent,
    transparent
  );
  background-size: 300% 300%;
  animation: aura-shine var(--aura-duration) ease-in-out infinite;
}

.aura-beam[data-variant='shine']::before {
  filter: blur(8px);
  opacity: 0.7;
  animation: aura-shine var(--aura-duration) ease-in-out infinite;
}

.aura-beam[data-variant='shine']::after {
  filter: blur(26px);
  opacity: 0.42;
  animation: aura-shine var(--aura-duration) ease-in-out infinite;
}

/* ─── Glow variant (cursor proximity) ─────────────────────────────────────── */

@property --aura-glow-opacity {
  syntax: '<number>';
  initial-value: 0;
  inherits: true;
}

.aura-beam[data-variant='glow'] {
  --aura-x: 50%;
  --aura-y: 0px;
  --aura-cone: 140px;
  --aura-color-third: var(--aura-color-to);

  animation: none;
  transition: --aura-glow-opacity 0.18s ease;
  background-origin: border-box;

  background-image: radial-gradient(
    circle var(--aura-cone) at var(--aura-x) var(--aura-y),
    color-mix(
        in srgb,
        var(--aura-color-from) calc(var(--aura-glow-opacity) * 100%),
        transparent
      )
      0%,
    color-mix(
        in srgb,
        var(--aura-color-to) calc(var(--aura-glow-opacity) * 78%),
        transparent
      )
      45%,
    color-mix(
        in srgb,
        var(--aura-color-third) calc(var(--aura-glow-opacity) * 50%),
        transparent
      )
      75%,
    transparent 100%
  );
}

.aura-beam[data-variant='glow']::before {
  filter: blur(5px);
  opacity: 0.85;
}

.aura-beam[data-variant='glow']::after {
  filter: blur(24px);
  opacity: 0.5;
}
